    return true;
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) return s;
    java.util.TreeMap<Character, Integer> freq = new java.util.TreeMap<>();
    for (char c : s.toCharArray()) {
        freq.put(c, freq.getOrDefault(c, 0) + 1);
    }
    StringBuilder result = new StringBuilder();
    while (!freq.isEmpty()) {
        // Ascending pass: pick smallest, then smallest greater than last
        java.util.Map.Entry<Character, Integer> e = freq.firstEntry();
        char last = e.getKey();
        result.append(last);
        if (e.getValue() == 1) freq.remove(last); else freq.put(last, e.getValue() - 1);
        while (true) {
            java.util.Map.Entry<Character, Integer> next = freq.higherEntry(last);
            if (next == null) break;
            last = next.getKey();
            result.append(last);
            if (next.getValue() == 1) freq.remove(last); else freq.put(last, next.getValue() - 1);
        }
        if (freq.isEmpty()) break;

        // Descending pass: pick largest, then largest smaller than last
        java.util.Map.Entry<Character, Integer> e2 = freq.lastEntry();
        char lastD = e2.getKey();
        result.append(lastD);
        if (e2.getValue() == 1) freq.remove(lastD); else freq.put(lastD, e2.getValue() - 1);
        while (!freq.isEmpty()) {
            java.util.Map.Entry<Character, Integer> prev = freq.lowerEntry(lastD);
            if (prev == null) break;
            lastD = prev.getKey();
            result.append(lastD);
            if (prev.getValue() == 1) freq.remove(lastD); else freq.put(lastD, prev.getValue() - 1);
        }
    }
    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    int n = nums.length;
    int maxK = n / 2;
    if (maxK == 0) {
        return false;
    }

    @SuppressWarnings("unchecked")
    Set<Integer>[] dp = new Set[maxK + 1];
    for (int i = 0; i <= maxK; i++) {
        dp[i] = new java.util.HashSet<>();
    }
    dp[0].add(0);

    for (int num : nums) {
        for (int size = maxK; size >= 1; size--) {
            if (dp[size - 1].isEmpty()) {
                continue;
            }
            for (int prevSum : dp[size - 1]) {
                dp[size].add(prevSum + num);
            }
        }
    }

    for (int k = 1; k <= maxK; k++) {
        if (((long) totalSum * k) % n != 0) {
            continue;
        }
        int target = totalSum * k / n;
        if (dp[k].contains(target)) {
            return true;
        }
    }
    return false;
}

