public boolean hasAllCodes(String s, int k) {
    if (k > s.length()) return false;
    int total = 1 << k;                     // number of possible binary strings of length k
    boolean[] seen = new boolean[total];     // track which patterns have appeared
    int mask = total - 1;                    // mask to keep only k bits
    int code = 0;                            // current sliding window as integer
    int seenCount = 0;

    for (int i = 0; i < s.length(); i++) {
        code = ((code << 1) & mask) | (s.charAt(i) - '0'); // shift left, add new bit
        if (i >= k - 1) {                      // window is fully formed
            if (!seen[code]) {
                seen[code] = true;
                seenCount++;
                if (seenCount == total) return true;  // all patterns found
            }
        }
    }
    return seenCount == total;
}

