public int kthFactor(int n, int k) {
    ArrayList<Integer> divisors = new ArrayList<>();
    int sqrt = (int) Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            divisors.add(i);
            if (i != n / i) {
                divisors.add(n / i);
            }
        }
    }
    Collections.sort(divisors);
    if (divisors.size() < k) {
        return -1;
    } else {
        return divisors.get(k - 1);
    }
}

