        result.add(0);
    }
    Queue<Long> queue = new LinkedList<>();
    for (int i = 1; i <= 9; i++) {
        queue.offer((long) i);
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > high) {
            continue;
        }
        if (num >= low) {
            result.add((int) num);
        }
        long lastDigit = num % 10;
        if (lastDigit > 0) {
            long next = num * 10 + (lastDigit - 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
        if (lastDigit < 9) {
            long next = num * 10 + (lastDigit + 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
    }
    Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    long count = 0;
    long factor = 1;
    while (factor <= n) {
        long lower = n % factor;
        long current = (n / factor) % 10;
        long higher = n / (factor * 10);

        if (current == 0) {
            count += higher * factor;
        } else if (current == 1) {
            count += higher * factor + lower + 1;
        } else {
            count += (higher + 1) * factor;
        }

        factor *= 10;
    }
    return (int) count;
}

