    if (n == 0) {
        return new int[0];
    }
    int total = m * n;
    int[] result = new int[total];
    int index = 0;
    int maxSum = m + n - 2;
    for (int s = 0; s <= maxSum; s++) {
        if (s % 2 == 0) {
            int row = Math.min(s, m - 1);
            int col = s - row;
            while (row >= 0 && col < n) {
                result[index++] = mat[row][col];
                row--;
                col++;
            }
        } else {
            int col = Math.min(s, n - 1);
            int row = s - col;
            while (row < m && col >= 0) {
                result[index++] = mat[row][col];
                row++;
                col--;
            }
        }
    }
    return result;
}

