    }
    // swap i and j
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    // reverse suffix from i+1 to end
    int left = i + 1, right = digits.length - 1;
    while (left < right) {
        char t = digits[left];
        digits[left] = digits[right];
        digits[right] = t;
        left++;
        right--;
    }
    return Integer.parseInt(new String(digits));
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];
    // Ensure all points are distinct
    if ((x1 == x2 && y1 == y2) ||
        (x1 == x3 && y1 == y3) ||
        (x2 == x3 && y2 == y3)) {
        return false;
    }
    // Cross product of vectors (p1->p2) and (p1->p3)
    int cross = (x2 - x1) * (y3 - y1) - (y2 - y1) * (x3 - x1);
    return cross != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) return 0;
    int[] ugly = new int[n];
    ugly[0] = 1;
    int idx2 = 0, idx3 = 0, idx5 = 0;
    int next2 = 2, next3 = 3, next5 = 5;
    for (int i = 1; i < n; i++) {
        int nextUgly = Math.min(next2, Math.min(next3, next5));
        ugly[i] = nextUgly;
        if (nextUgly == next2) {
            idx2++;
            next2 = ugly[idx2] * 2;
        }
        if (nextUgly == next3) {
            idx3++;
            next3 = ugly[idx3] * 3;
        }
        if (nextUgly == next5) {
            idx5++;
            next5 = ugly[idx5] * 5;
        }
    }
    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.length() == 0) {
        return 0;
    }
    int maxLen = 1;
    int currentLen = 1;
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentLen++;
            if (currentLen > maxLen) {
                maxLen = currentLen;
            }
        } else {
            currentLen = 1;
        }
    }
    return maxLen;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    ArrayDeque<Long> stack = new ArrayDeque<>();
    for (int i = 9; i >= 1 && i <= n; i--) {
        stack.push((long) i);
    }
    while (!stack.isEmpty()) {
        long curr = stack.pop();
        if (curr > n) {
            continue;
        }
        result.add((int) curr);
        for (int i = 9; i >= 0; i--) {
            stack.push(curr * 10 + i);
        }
    }
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    Map<Integer, Integer> freq = new HashMap<>();
    for (int n : nums) {
        freq.put(n, freq.getOrDefault(n, 0) + 1);
    }
    int sum = 0;
    for (Map.Entry<Integer, Integer> entry : freq.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) return 0;
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        int min = Integer.MAX_VALUE;
        int j = 1;
        while (j * j <= i) {
            int candidate = dp[i - j * j] + 1;
            if (candidate < min) {
                min = candidate;
            }
            j++;
        }
        dp[i] = min;
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }
    StringBuilder result = new StringBuilder();
    StringBuilder word = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == ' ') {
            for (int j = word.length() - 1; j >= 0; j--) {
                result.append(word.charAt(j));
            }
            word.setLength(0);
            result.append(c); // preserve the space
        } else {
            word.append(c);
        }
    }
    for (int j = word.length() - 1; j >= 0; j--) {
        result.append(word.charAt(j));
    }
    return result.toString();
}
